const manualesPorConsulta = `-- name: ManualesPorConsulta :many
SELECT id, empresa_id, titulo, resumen, cuerpo, etiquetas, equipo, visibilidad, activo, busqueda, creado_por, version, created_at, updated_at FROM mensajeria.manuales
WHERE coalesce(empresa_id, 0) = $1::bigint AND activo AND busqueda @@ to_tsquery('spanish', $2::text)
ORDER BY ts_rank(busqueda, to_tsquery('spanish', $2::text)) DESC, id DESC LIMIT 5
`

type ManualesPorConsultaParams struct {
	Empresa  int64
	Consulta string
}

func (q *Queries) ManualesPorConsulta(ctx context.Context, arg ManualesPorConsultaParams) ([]MensajeriaManuale, error) {
	rows, err := q.db.Query(ctx, manualesPorConsulta, arg.Empresa, arg.Consulta)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []MensajeriaManuale
	for rows.Next() {
		var i MensajeriaManuale
		if err := rows.Scan(
			&i.ID,
			&i.EmpresaID,
			&i.Titulo,
			&i.Resumen,
			&i.Cuerpo,
			&i.Etiquetas,
			&i.Equipo,
			&i.Visibilidad,
			&i.Activo,
			&i.Busqueda,
			&i.CreadoPor,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

